using System;
using MlmDesktop;
internal static class ContactTests {
 static int neighborRadius=2;static ClothContacts CreateContacts(int columns,int rows){return new ClothContacts(columns,rows,1.0/120,neighborRadius);}

 static int failures;
 static void Check(bool condition,string message){if(!condition){failures++;Console.WriteLine("FAIL: "+message);}}
 static V3[] Fixture(){var p=new V3[16];for(int i=0;i<p.Length;i++)p[i]=new V3(0,0,50);p[0]=new V3(0,0,50);p[8]=new V3(0,0,80);p[1]=new V3(0,30,50);return p;}
 static double Dot(V3 a,V3 b){return a.X*b.X+a.Y*b.Y+a.Z*b.Z;}
 static V3 Cross(V3 a,V3 b){return new V3(a.Y*b.Z-a.Z*b.Y,a.Z*b.X-a.X*b.Z,a.X*b.Y-a.Y*b.X);}
 static double FaceDistance(V3[] p,int i){V3 n=Cross(p[8]-p[0],p[1]-p[0]);return Dot(p[i]-p[0],n)/n.Length;}
 // Removing 3D normals makes a vertical fold pass through its opposite face.
 static void VerticalFoldHasThickness(){var p=Fixture();p[7]=new V3(1,10,60);var start=(V3[])p.Clone();CreateContacts(8,2).Resolve(p,start,-1);Check(FaceDistance(p,7)<-2,"vertical fold must retain at least two units of normal clearance, got "+FaceDistance(p,7));}
 // Using only final proximity allows a fast point to switch sides completely.
 static void FastVertexCannotSwapLayers(){var start=Fixture();start[7]=new V3(12,10,60);var p=(V3[])start.Clone();p[7]=new V3(-12,10,60);CreateContacts(8,2).Resolve(p,start,-1);Check(FaceDistance(p,7)<-2,"swept vertex must stay on its original side of vertical face, got "+FaceDistance(p,7));}
 // Rejecting contacts outside the final footprint misses this diagonal crossing.
 static void CrossingOutsideFinalTriangleStillStops(){var start=Fixture();start[7]=new V3(12,10,60);var p=(V3[])start.Clone();p[7]=new V3(-12,29,60);CreateContacts(8,2).Resolve(p,start,-1);Check(FaceDistance(p,7)<-2,"swept diagonal crossing must retain its original face side, got "+FaceDistance(p,7));}
 // A locked cursor point must remain exact even when contact moves its support.
 static void HeldPointRemainsPinned(){var p=Fixture();p[7]=new V3(1,10,60);V3 held=p[7];CreateContacts(8,2).Resolve(p,(V3[])p.Clone(),7);Check((p[7]-held).Length<1e-9,"held point moved during self-contact");}
 // Existing desktop behavior: stacked horizontal panels retain clearance.
 static void FloorStackKeepsThickness(){var p=Fixture();for(int i=0;i<p.Length;i++){V3 v=p[i];p[i]=new V3(v.Y,v.Z-50,0);}p[7]=new V3(10,10,1);CreateContacts(8,2).Resolve(p,(V3[])p.Clone(),-1);Check(p[7].Z>=2,"folded panel penetrated floor-supported panel");for(int i=0;i<p.Length;i++)Check(p[i].Z>=0,"contact moved vertex below desktop");}
 // Collapsed strip edges can cross without a vertex entering any triangle.
 static V3[] EdgeFixture(double height){var p=new V3[16];for(int i=0;i<8;i++)p[i]=new V3(100,100,50);p[0]=new V3(-20,0,50);p[1]=new V3(20,0,50);p[6]=new V3(0,-20,height);p[7]=new V3(0,20,height);for(int i=0;i<8;i++)p[i+8]=p[i];return p;}
 static void CrossingEdgesHaveThickness(){var p=EdgeFixture(51);CreateContacts(8,2).Resolve(p,(V3[])p.Clone(),-1);double gap=(p[6].Z+p[7].Z-p[0].Z-p[1].Z)*.5;Check(gap>=2,"crossing edges need normal clearance without a vertex/face hit, got "+gap);}
 static void FastEdgesCannotSwapLayers(){var start=EdgeFixture(62);var p=EdgeFixture(38);CreateContacts(8,2).Resolve(p,start,-1);double gap=(p[6].Z+p[7].Z-p[0].Z-p[1].Z)*.5;Check(gap>=2,"swept edges must retain their original layer order, got "+gap);}
 // A later strain projection must be able to restore a cached contact without
 // rebuilding broadphase data or forgetting its original layer side.
 static void CachedContactRestoresClearance(){var p=Fixture();p[7]=new V3(1,10,60);var solver=CreateContacts(8,2);solver.Resolve(p,(V3[])p.Clone(),-1);p[7].X-=3;var method=typeof(ClothContacts).GetMethod("ProjectExisting",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);if(method!=null)method.Invoke(solver,new object[]{p,-1,4});Check(FaceDistance(p,7)<-2,"cached contact did not restore clearance after strain projection, got "+FaceDistance(p,7));}
 // Coincident layers need a consistent initial order, otherwise reciprocal
 // contacts push each panel above the other on every projection.
 static void CoincidentFoldConverges(){const int columns=13,rows=5;var p=new V3[columns*rows];for(int y=0;y<rows;y++)for(int x=0;x<columns;x++)p[y*columns+x]=new V3(x>7?280-x*20:x*20,y*20,0);var start=(V3[])p.Clone();var solver=CreateContacts(columns,rows);double motion=0;for(int n=0;n<40;n++){Array.Copy(p,start,p.Length);solver.Resolve(p,start,-1);motion=0;for(int i=0;i<p.Length;i++)motion+=(p[i]-start[i]).LengthSquared;motion=Math.Sqrt(motion/p.Length);}Check(motion<.05,"coincident fold must converge without contradictory contact jitter, RMS="+motion);}
 // Going around the finite triangle edge is legal: preserving the old infinite
 // plane side here invents a collision and pumps energy into a turning fold.
 static void MovingAroundFaceEdgeKeepsNewSide(){var start=Fixture();for(int x=2;x<4;x++)start[x]=start[x+8]=start[1];for(int x=4;x<8;x++)start[x]=start[x+8]=new V3(12,40,60);var p=(V3[])start.Clone();for(int x=4;x<8;x++)p[x]=p[x+8]=new V3(-1,19,60);CreateContacts(8,2).Resolve(p,start,-1);Check(FaceDistance(p,7)>2,"moving around a face edge must stay on the newly reached side, got "+FaceDistance(p,7));}
 // The support tolerance used for friction must also survive broadphase culling.
 static void NearRestContactRetainsSupport(){var p=Fixture();for(int i=0;i<p.Length;i++){V3 v=p[i];p[i]=new V3(v.Y,v.Z-50,0);}p[7]=new V3(10,10,4);var solver=CreateContacts(8,2);solver.Resolve(p,(V3[])p.Clone(),-1);Check(solver.Supported[7],"near-rest layer lost its contact support inside the friction tolerance");}
 // Mutually incompatible contacts in a collapsed multilayer fold must spend a
 // finite shared correction budget, including later cached projection passes.
 static void DenseContactsHaveBoundedProjection(){const int columns=15,rows=7;var p=new V3[columns*rows];for(int y=0;y<rows;y++)for(int x=0;x<columns;x++)p[y*columns+x]=new V3((x%3)*20,y*20,0);var start=(V3[])p.Clone();var solver=CreateContacts(columns,rows);solver.Resolve(p,start,-1);solver.ProjectExisting(p,-1,20);double largest=0;for(int i=0;i<p.Length;i++)largest=Math.Max(largest,(p[i]-start[i]).Length);Check(largest<=7.001,"stationary dense contacts exceeded their shared projection budget, max displacement="+largest);}
 // A rotating face can cross the infinite plane once outside its boundary,
 // then meet the point from the opposite side at the later valid impact.
 static void LaterFaceCrossingUsesImpactSide(){var start=Fixture();start[8]=new V3(100,0,50);start[1]=new V3(0,100,50);start[7]=new V3(50,100,68.75);var p=(V3[])start.Clone();p[1]=new V3(0,100,150);p[7]=new V3(50,0,68.75);var solver=CreateContacts(8,2);var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
 // Isolate this one actual primitive: the remaining collapsed fixture edges
 // have unrelated simultaneous swept contacts during the large face rotation.
 typeof(ClothContacts).GetField("stamp",flags).SetValue(solver,1);typeof(ClothContacts).GetField("queryLow",flags).SetValue(solver,new V3(double.NegativeInfinity,double.NegativeInfinity,double.NegativeInfinity));typeof(ClothContacts).GetField("queryHigh",flags).SetValue(solver,new V3(double.PositiveInfinity,double.PositiveInfinity,double.PositiveInfinity));var budget=(double[])typeof(ClothContacts).GetField("remainingCorrection",flags).GetValue(solver);for(int i=0;i<budget.Length;i++)budget[i]=1000;typeof(ClothContacts).GetMethod("VertexTriangle",flags).Invoke(solver,new object[]{7,0,p,start});solver.ProjectExisting(p,-1,4);V3 relative=p[7]-(p[0]*.25+p[8]*.5+p[1]*.25);double gap=Dot(relative,new V3(0,.6,-.8));Check(gap>=2,"later finite-face crossing used the earlier outside-face plane side, gap="+gap);}
 // Net displacement is not a contact normal at a corner. Both independent
 // inward components must be removed while unpinned contact momentum balances.
 static void OrthogonalContactsProjectRelativeVelocity(){var p=new V3[16];for(int i=0;i<p.Length;i++)p[i]=new V3(0,0,50);p[7]=new V3(1,1,50);p[0]=new V3(0,1,50);p[1]=new V3(1,0,50);var solver=CreateContacts(8,2);var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;var add=typeof(ClothContacts).GetMethod("Add",flags);add.Invoke(solver,new object[]{7,0,2,3,1.0,-1.0,0.0,0.0,new V3(1,0,0),false});add.Invoke(solver,new object[]{7,1,2,3,1.0,-1.0,0.0,0.0,new V3(0,1,0),false});var velocity=new V3[16];velocity[7]=new V3(-3,-4,2);var method=typeof(ClothContacts).GetMethod("ProjectVelocities",flags);if(method!=null)method.Invoke(solver,new object[]{p,velocity,-1});Check(velocity[7].X-velocity[0].X>=-1e-6&&velocity[7].Y-velocity[1].Y>=-1e-6,"orthogonal contacts retained an inward relative velocity");V3 total=new V3();for(int i=0;i<velocity.Length;i++)total+=velocity[i];Check((total-new V3(-3,-4,2)).Length<1e-8,"free contact impulses did not conserve linear momentum");}
 static void HeldFastVertexCannotSwapLayers(){var start=Fixture();start[7]=new V3(12,10,60);var p=(V3[])start.Clone();p[7]=new V3(-12,10,60);CreateContacts(8,2).Resolve(p,start,7);Check((p[7]-new V3(-12,10,60)).Length<1e-8,"swept held point was unpinned");Check(FaceDistance(p,7)<-2,"held fast vertex exhausted stationary support budgets and swapped layers, gap="+FaceDistance(p,7));}
 // Reciprocal contacts on identical-winding coincident patches must agree on
 // which material layer is higher, instead of asking both layers to be below.
 static void CoincidentSameWindingContactsAgree(){var p=new V3[16];for(int i=0;i<p.Length;i++)p[i]=new V3(0,0,50);p[8]=p[14]=new V3(0,30,50);p[1]=p[7]=new V3(30,0,50);var start=(V3[])p.Clone();var solver=CreateContacts(8,2);var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(ClothContacts).GetField("queryLow",flags).SetValue(solver,new V3(double.NegativeInfinity,double.NegativeInfinity,double.NegativeInfinity));typeof(ClothContacts).GetField("queryHigh",flags).SetValue(solver,new V3(double.PositiveInfinity,double.PositiveInfinity,double.PositiveInfinity));var budget=(double[])typeof(ClothContacts).GetField("remainingCorrection",flags).GetValue(solver);for(int i=0;i<budget.Length;i++)budget[i]=1000;var narrowphase=typeof(ClothContacts).GetMethod("VertexTriangle",flags);typeof(ClothContacts).GetField("stamp",flags).SetValue(solver,1);narrowphase.Invoke(solver,new object[]{0,12,p,start});typeof(ClothContacts).GetField("stamp",flags).SetValue(solver,2);narrowphase.Invoke(solver,new object[]{6,0,p,start});solver.ProjectExisting(p,-1,20);Check(p[6].Z-p[0].Z>=2,"reciprocal same-winding contacts chose contradictory layer directions, gap="+(p[6].Z-p[0].Z));}
 static void Benchmark(){
  foreach(bool folded in new[]{false,true}){
   var p=new V3[33*23];for(int y=0;y<23;y++)for(int x=0;x<33;x++)p[y*33+x]=new V3(folded&&x>20?800-x*20:x*20,y*20,folded&&x>20?3.5:0);
   var solver=CreateContacts(33,23);var start=(V3[])p.Clone();for(int i=0;i<20;i++)solver.Resolve(p,start,-1);Array.Copy(p,start,p.Length);
   GC.Collect();GC.WaitForPendingFinalizers();int collections=GC.CollectionCount(0);TimeSpan cpu=System.Diagnostics.Process.GetCurrentProcess().TotalProcessorTime;var watch=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<300;i++)solver.Resolve(p,start,-1);watch.Stop();double cpuMs=(System.Diagnostics.Process.GetCurrentProcess().TotalProcessorTime-cpu).TotalMilliseconds/300;
   Console.WriteLine((folded?"Folded":"Flat")+" contacts: "+(watch.Elapsed.TotalMilliseconds/300).ToString("F3")+" ms/tick (CPU "+cpuMs.ToString("F3")+"); Gen0 collections="+(GC.CollectionCount(0)-collections));
  }
 }
 static void LaterProjectionKeepsLayerOrder(){var p=Fixture();p[7]=new V3(8,10,60);var solver=CreateContacts(8,2);solver.Resolve(p,(V3[])p.Clone(),-1);p[7].X=-1;solver.ProjectExisting(p,-1,4);Check(FaceDistance(p,7)<-2,"elastic projection crossed a nearby uncached layer, gap="+FaceDistance(p,7));}
 static void OpposingProjectionsKeepLayerOrder(){var p=Fixture();p[7]=new V3(12,10,60);var solver=CreateContacts(8,2);solver.Resolve(p,(V3[])p.Clone(),-1);p[7].X=5;p[0].X=p[8].X=p[1].X=6;solver.ProjectExisting(p,-1,4);Check(FaceDistance(p,7)<-2,"opposing elastic projections crossed uncached layers, gap="+FaceDistance(p,7));}
 static void CoplanarSlideIsNotACrossing(){var p=new V3[16];for(int i=0;i<p.Length;i++)p[i]=new V3(0,0,50);p[8]=p[14]=new V3(0,30,50);p[1]=p[7]=new V3(30,0,50);var start=(V3[])p.Clone();start[0].X-=1;start[1].X-=1;start[8].X-=1;start[6].X+=1;start[7].X+=1;start[14].X+=1;var solver=CreateContacts(8,2);var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(ClothContacts).GetField("queryLow",flags).SetValue(solver,new V3(double.NegativeInfinity,double.NegativeInfinity,double.NegativeInfinity));typeof(ClothContacts).GetField("queryHigh",flags).SetValue(solver,new V3(double.PositiveInfinity,double.PositiveInfinity,double.PositiveInfinity));var budget=(double[])typeof(ClothContacts).GetField("remainingCorrection",flags).GetValue(solver);for(int i=0;i<budget.Length;i++)budget[i]=1000;var narrow=typeof(ClothContacts).GetMethod("VertexTriangle",flags);typeof(ClothContacts).GetField("stamp",flags).SetValue(solver,1);narrow.Invoke(solver,new object[]{0,12,p,start});typeof(ClothContacts).GetField("stamp",flags).SetValue(solver,2);narrow.Invoke(solver,new object[]{6,0,p,start});Check(solver.SweptContactCount==0,"lateral coplanar sliding manufactured a swept layer crossing");solver.ProjectExisting(p,-1,20);Check(p[6].Z-p[0].Z>=2,"coplanar sliding lost consistent material layer order");}
 static void RepairCorrectionIsAccounted(){var start=Fixture();start[7]=new V3(12,10,60);var p=(V3[])start.Clone();p[7]=new V3(-12,10,60);var before=(V3[])p.Clone();var solver=CreateContacts(8,2);solver.Resolve(p,start,-1);double moved=0;for(int i=0;i<p.Length;i++)moved=Math.Max(moved,(p[i]-before[i]).Length);Check(solver.MaximumCorrection+1e-8>=moved,"CCD repair disappeared from the shared correction accounting");}
 public static int Main(string[] args){if(Array.IndexOf(args,"--desktop")>=0)neighborRadius=1;CoplanarSlideIsNotACrossing();RepairCorrectionIsAccounted();OpposingProjectionsKeepLayerOrder();LaterProjectionKeepsLayerOrder();HeldFastVertexCannotSwapLayers();CoincidentSameWindingContactsAgree();OrthogonalContactsProjectRelativeVelocity();LaterFaceCrossingUsesImpactSide();DenseContactsHaveBoundedProjection();NearRestContactRetainsSupport();MovingAroundFaceEdgeKeepsNewSide();CoincidentFoldConverges();CachedContactRestoresClearance();CrossingEdgesHaveThickness();FastEdgesCannotSwapLayers();VerticalFoldHasThickness();FastVertexCannotSwapLayers();CrossingOutsideFinalTriangleStillStops();HeldPointRemainsPinned();FloorStackKeepsThickness();if(args.Length>0&&args[0]=="--benchmark")Benchmark();Console.WriteLine(failures==0?"Contact geometry tests passed.":failures+" contact geometry test(s) failed.");return failures==0?0:1;}
}